INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", 2.1, 100, "ヤマト", 0.0, 1, 3001, -416.5, "2030/01/01 14:59:59", 130011, 3001100, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", 5.68, 101, "ヤマト", 0.0, 4, 3001, -416.5, "2030/01/01 14:59:59", 130011, 3001101, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", 0.0, 102, "ヤマト", 0.0, 1, 3001, -416.5, "2030/01/01 14:59:59", 130011, 3001102, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", 0.0, 100, "フブキ", 0.0, 1, 3002, -416.5, "2030/01/01 14:59:59", 130211, 3002100, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", 0.0, 101, "フブキ", 0.0, 1, 3002, -416.5, "2030/01/01 14:59:59", 130211, 3002101, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", 8.53, 102, "フブキ", 0.0, 5, 3002, -416.5, "2030/01/01 14:59:59", 130211, 3002102, 2);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", 5.67, 103, "フブキ", 0.0, 7, 3002, -416.5, "2030/01/01 14:59:59", 130211, 3002103, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", 0.0, 104, "フブキ", 0.0, 1, 3002, -416.5, "2030/01/01 14:59:59", 130211, 3002104, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", 0.0, 300, "フブキ", 0.0, 3, 3004, -416.5, "2030/01/01 14:59:59", 130211, 3002300, 3);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", 0.0, 301, "フブキ", 0.0, 7, 3005, -416.5, "2030/01/01 14:59:59", 130211, 3002400, 7);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", 4.4, 200, "フブキ", 0.0, 2, 3003, -416.5, "2030/01/01 14:59:59", 130211, 3003200, 1);
INSERT INTO `v1_c25f4d3a46fbcce5836c86dc6a758817084a73bee6205a5429c064049cde9885` VALUES ("2024/10/31 12:00:00", "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", 0.0, 201, "フブキ", 0.0, 7, 3003, -416.5, "2030/01/01 14:59:59", 130211, 3003201, 7);
